PurchaseOrders = {
    states: [script[TransactionStates]],
     init: async function(app, container) {
         var poGrid = [script[PurchaseOrderGrid]];
        api.addToMetaCache([
            {
                "Name": "B2B",
                "Types": [
                    [meta[B2B/PurchaseOrder]]
                ]
            }
        ]);
         var dataSource = await model.getDatasource({endpoint: "B2B/PurchaseOrder", odataAppend: "/FromSystem(SystemId='" + app.Config.B2B.TransactionSource + "')?$expand=References,Companies"});
         var variables = {
             element: $("[name=poGrid]", container),
             dataSource: dataSource
         };
         await poGrid(variables);
         variables.PurchaseOrderGrid.init();
     }
};
